--
-- Structure for view `view_all_sales`
--
DROP TABLE IF EXISTS `view_all_sales`;

CREATE ALGORITHM=UNDEFINED DEFINER=`technopa_distributor`@`localhost` SQL SECURITY DEFINER VIEW `view_all_sales`  AS SELECT `order_products`.`product_id` AS `product_id`, `products`.`name` AS `product_name`, `products`.`code` AS `product_code`, `products`.`category_id` AS `category_id`, `categories`.`name` AS `category_name`, `attributes`.`name` AS `attribute_name`, `order_products`.`sale_price` AS `rate`, `order_products`.`quantity` AS `qty`, `order_products`.`subtotal`- `order_products`.`return_amount` - `order_products`.`discount` AS `amount`, `orders`.`store_id` AS `store_id`, `orders`.`date` AS `date` FROM ((((`order_products` left join `products` on(`products`.`id` = `order_products`.`product_id`)) left join `attributes` on(`attributes`.`id` = `products`.`attribute_id`)) left join `categories` on(`categories`.`id` = `products`.`category_id`)) left join `orders` on(`orders`.`id` = `order_products`.`order_id`)) WHERE `orders`.`deleted_at` is null AND `orders`.`status` in ('Delivered','On Route','Collected') AND `products`.`deleted_at` is null AND `products`.`status` = 1union allselect `sales_lists`.`product_id` AS `product_id`,`products`.`name` AS `product_name`,`products`.`code` AS `product_code`,`products`.`category_id` AS `category_id`,`categories`.`name` AS `category_name`,`attributes`.`name` AS `attribute_name`,`sales_lists`.`rate` AS `rate`,`sales_lists`.`qty` AS `qty`,`sales_lists`.`amount` - `sales_lists`.`discount` AS `amount`,`sales`.`store_id` AS `store_id`,`sales`.`date` AS `date` from ((((`sales_lists` left join `sales` on(`sales`.`id` = `sales_lists`.`sales_id`)) left join `products` on(`products`.`id` = `sales_lists`.`product_id`)) left join `attributes` on(`attributes`.`id` = `products`.`attribute_id`)) left join `categories` on(`categories`.`id` = `products`.`category_id`)) where `sales`.`deleted_at` is null and `products`.`deleted_at` is null and `products`.`status` = 1  ;

-- --------------------------------------------------------

--
-- Structure for view `view_client_collections`
--
DROP TABLE IF EXISTS `view_client_collections`;

CREATE ALGORITHM=UNDEFINED DEFINER=`technopa_distributor`@`localhost` SQL SECURITY DEFINER VIEW `view_client_collections`  AS SELECT `clients`.`id` AS `client_id`, `collections`.`payment_date` AS `payment_date`, `collections`.`collection_type` AS `collection_type`, `collections`.`amount` AS `amount` FROM (`clients` left join `collections` on(`clients`.`id` = `collections`.`client_id` and `collections`.`collection_type` <> 'adjust' and `collections`.`deleted_at` is null)) ;

-- --------------------------------------------------------

--
-- Structure for view `view_client_realization_sales`
--
DROP TABLE IF EXISTS `view_client_realization_sales`;

CREATE ALGORITHM=UNDEFINED DEFINER=`technopa_distributor`@`localhost` SQL SECURITY DEFINER VIEW `view_client_realization_sales`  AS SELECT `sales`.`company_id` AS `company_id`, `sales`.`client_id` AS `client_id`, `clients`.`client_category_id` AS `client_category_id`, `client_categories`.`name` AS `client_category_name`, `clients`.`name` AS `client_name`, `clients`.`phone` AS `client_phone`, `clients`.`code` AS `client_code`, `areas`.`region_id` AS `region_id`, `regions`.`name` AS `region_name`, `clients`.`area_id` AS `area_id`, `areas`.`name` AS `area_name`, `clients`.`territory_id` AS `territory_id`, `territories`.`name` AS `territory_name`, `sales`.`date` AS `date`, `sales`.`total_amount`- `sales`.`discount` AS `amount`, `sales`.`total_paid` AS `total_paid`, `sales`.`staff_id` AS `staff_id`, `staff`.`name` AS `staff_name` FROM ((((((`sales` left join `clients` on(`clients`.`id` = `sales`.`client_id`)) left join `areas` on(`areas`.`id` = `clients`.`area_id`)) left join `regions` on(`regions`.`id` = `areas`.`region_id`)) left join `territories` on(`territories`.`id` = `clients`.`territory_id`)) left join `staff` on(`staff`.`id` = `sales`.`staff_id`)) left join `client_categories` on(`client_categories`.`id` = `clients`.`client_category_id`)) WHERE `clients`.`deleted_at` is null AND `sales`.`deleted_at` is null ;

-- --------------------------------------------------------

--
-- Structure for view `view_client_returns`
--
DROP TABLE IF EXISTS `view_client_returns`;

CREATE ALGORITHM=UNDEFINED DEFINER=`technopa_distributor`@`localhost` SQL SECURITY DEFINER VIEW `view_client_returns`  AS SELECT `clients`.`company_id` AS `company_id`, `clients`.`id` AS `client_id`, `client_categories`.`id` AS `client_category_id`, `client_categories`.`name` AS `client_category_name`, `sales_returns`.`date` AS `date`, `sales_return_lists`.`amount`- `sales_return_lists`.`sales_discount` AS `amount` FROM (((`clients` left join `sales_returns` on(`clients`.`id` = `sales_returns`.`client_id` and `sales_returns`.`deleted_at` is null)) left join `client_categories` on(`client_categories`.`id` = `clients`.`client_category_id` and `client_categories`.`deleted_at` is null)) left join `sales_return_lists` on(`sales_returns`.`id` = `sales_return_lists`.`sales_return_id`)) WHERE `clients`.`deleted_at` is null ;

-- --------------------------------------------------------

--
-- Structure for view `view_client_sales`
--
DROP TABLE IF EXISTS `view_client_sales`;

CREATE ALGORITHM=UNDEFINED DEFINER=`technopa_distributor`@`localhost` SQL SECURITY DEFINER VIEW `view_client_sales`  AS SELECT `sales_lists`.`company_id` AS `company_id`, `sales_lists`.`client_id` AS `client_id`, `client_categories`.`id` AS `client_category_id`, `client_categories`.`name` AS `client_category_name`, `clients`.`name` AS `client_name`, `clients`.`phone` AS `client_phone`, `clients`.`code` AS `client_code`, `regions`.`id` AS `region_id`, `regions`.`name` AS `region_name`, `areas`.`id` AS `area_id`, `areas`.`name` AS `area_name`, `territories`.`id` AS `territory_id`, `territories`.`name` AS `territory_name`, `sales`.`date` AS `date`, sum(`sales_lists`.`amount`) - sum(`sales_lists`.`discount`) - sum(`sales_lists`.`returned_amount`) AS `amount`, `sales`.`total_paid` AS `total_paid`, `staff`.`id` AS `staff_id`, `staff`.`name` AS `staff_name` FROM (((((((`sales_lists` left join `sales` on(`sales`.`id` = `sales_lists`.`sales_id`)) left join `clients` on(`clients`.`id` = `sales`.`client_id`)) left join `staff` on(`staff`.`id` = `sales`.`staff_id` and `staff`.`deleted_at` is null)) left join `client_categories` on(`client_categories`.`id` = `clients`.`client_category_id` and `client_categories`.`deleted_at` is null)) left join `areas` on(`areas`.`id` = `clients`.`area_id` and `areas`.`deleted_at` is null)) left join `regions` on(`regions`.`id` = `areas`.`region_id` and `regions`.`deleted_at` is null)) left join `territories` on(`territories`.`id` = `clients`.`territory_id` and `territories`.`deleted_at` is null)) WHERE `sales`.`deleted_at` is null AND `clients`.`deleted_at` is null GROUP BY `sales_lists`.`sales_id` ;

-- --------------------------------------------------------

--
-- Structure for view `view_collectionable_sales`
--
DROP TABLE IF EXISTS `view_collectionable_sales`;

CREATE ALGORITHM=UNDEFINED DEFINER=`technopa_distributor`@`localhost` SQL SECURITY DEFINER VIEW `view_collectionable_sales`  AS SELECT `sales`.`id` AS `id`, `sales`.`company_id` AS `company_id`, `sales`.`store_id` AS `store_id`, `sales`.`client_id` AS `client_id`, `clients`.`name` AS `client_name`, `sales`.`invoice` AS `invoice`, `sales`.`date` AS `date`, `sales`.`total_amount` AS `total_amount`, `sales`.`total_paid` AS `total_paid`, `sales`.`discount` AS `discount`, sum(`sales_lists`.`returned_amount`) AS `returned_amount`, `sales`.`total_amount`- sum(`sales_lists`.`returned_amount`) - `sales`.`discount` - `sales`.`total_paid` AS `collectionable_amount` FROM ((`sales_lists` left join `clients` on(`clients`.`id` = `sales_lists`.`client_id`)) left join `sales` on(`sales`.`id` = `sales_lists`.`sales_id`)) WHERE `sales`.`deleted_at` is null GROUP BY `sales`.`id` ;

-- --------------------------------------------------------

--
-- Structure for view `view_collection_history`
